double entropy(const vector<long long>& counts) {
 long long total = 0;
 for (auto c : counts) total += c;
 if (total == 0) return 0.0;

double H = 0.0;
 for (auto c : counts) {
 if (c == 0) continue;
 double p = (double)c / total;
 H -= p * (log(p) / log(2.0));
 }
 return H;
}
int main() {
